(()=>{'use strict';const shared=document.body.classList.contains('shared-app'),options=[['due','نزدیک‌ترین مهلت'],['new','جدیدترین کارها'],['updated','آخرین تغییرات'],['status','وضعیت انجام'],['owner','نام مسئول']],collator=new Intl.Collator('fa',{numeric:true,sensitivity:'base'}),valid=new Set(options.map(x=>x[0]));
const refinements=new Map();const stamp=s=>{const n=Date.parse(s||'');return Number.isFinite(n)?n:0};function data(row){if(row.dataset.taskSort){try{return JSON.parse(row.dataset.taskSort)}catch{return null}}const b=row.querySelector('[data-task],[data-shared-card]'),id=b?.dataset.task||b?.dataset.sharedCard,t=tasks.find(t=>t.id===id);if(!t)return null;const state=shared?t.status:clarityPhase(t),updated=shared?stamp(t.updated_at):Math.max(stamp(t.updated),stamp(t.created),...(t.reports||[]).map(r=>stamp(r.at||r.time)),...(t.assignmentHistory||[]).map(r=>stamp(r.at)));return{id:t.id,due:t.due||'',created:stamp(t.created_at||t.created),updated,status:{open:0,review:1,done:2}[state]??0,owner:shared?person(t.owner_id):people[t.owner]||'',title:t.title}}
function compare(a,b,mode){let n=0;if(mode==='due'){n=(a.status===2)-(b.status===2);if(!n)n=(a.due||'9999').localeCompare(b.due||'9999')}else if(mode==='new')n=b.created-a.created;else if(mode==='updated')n=b.updated-a.updated;else if(mode==='status')n=a.status-b.status;else if(mode==='owner')n=collator.compare(a.owner||'',b.owner||'');return n||(a.due||'9999').localeCompare(b.due||'9999')||collator.compare(a.title||'',b.title||'')||String(a.id).localeCompare(String(b.id))}
function attach(){const host=document.querySelector(shared?'#sharedApp':'#workspace');if(!host)return;const toolbar=host.querySelector('.personal-tools,.clarity-search,.shared-subtools');if(!toolbar)return;const uid=shared?session?.user.id:String(me()),personal=!!window.SAMANDIS_PERSONAL_MODE,pid=personal?document.querySelector('[data-personal-project].selected')?.dataset.personalProject:'team';const key='samandis-task-sort-v1:'+uid+':'+(shared?project?.id:'demo')+':'+pid;let mode='due';try{const saved=shared?SamandisPreferences.get('sort:'+project?.id+':'+pid):localStorage.getItem(key);if(valid.has(saved))mode=saved}catch{}let control=toolbar.querySelector('.task-sort-control');if(!control){control=document.createElement('label');control.className='task-sort-control';const text=document.createElement('span');text.textContent='مرتب‌سازی';const select=document.createElement('select');select.setAttribute('aria-label','مرتب‌سازی کارها');for(const [v,l] of options){const o=document.createElement('option');o.value=v;o.textContent=l;select.append(o)}control.append(text,select);toolbar.append(control)}let group=toolbar.querySelector('.task-view-tools');if(!group){group=document.createElement('div');group.className='task-view-tools';toolbar.append(group)}group.append(control);const layout=toolbar.querySelector('.desk-layout');if(layout)group.append(layout);const select=control.querySelector('select');select.value=mode;let refine=group.querySelector('.task-sort-refine');if(!refine){refine=document.createElement('select');refine.className='task-sort-refine';group.insertBefore(refine,layout||null)}let detail=refinements.get(key+':'+mode)||'';function refineOptions(){const choices=mode==='updated'?[['','جدید به قدیم'],['asc','قدیم به جدید']]:mode==='status'?[['','همه وضعیت‌ها'],['0','در دست اقدام'],['1','منتظر تأیید'],['2','تمام‌شده']]:mode==='owner'?[['','همه مسئولان'],...[...new Set([...host.querySelectorAll('tr,.desk-task-card,.personal-task-row')].map(data).filter(Boolean).map(t=>t.owner).filter(Boolean))].sort(collator.compare).map(n=>[n,n])]:[];refine.replaceChildren();for(const [value,label]of choices){const o=document.createElement('option');o.value=value;o.textContent=label;refine.append(o)}if(!choices.some(c=>c[0]===detail))detail='';refine.value=detail;refine.hidden=!choices.length;refine.setAttribute('aria-label',mode==='owner'?'انتخاب مسئول':mode==='status'?'انتخاب وضعیت':'ترتیب آخرین تغییرات')}refineOptions();function order(){for(const parent of host.querySelectorAll('.clarity-table tbody,.desk-lane,.personal-task-list')){const children=[...parent.children].filter(r=>r.matches('tr,.desk-task-card,.personal-task-row')),items=children.map(row=>({row,task:data(row)})).filter(x=>x.task);items.sort((a,b)=>mode==='updated'&&detail==='asc'?compare(b.task,a.task,mode):compare(a.task,b.task,mode));for(const item of items){const excluded=(mode==='status'&&detail!==''&&String(item.task.status)!==detail)||(mode==='owner'&&detail!==''&&item.task.owner!==detail);item.row.toggleAttribute('data-sort-filtered',excluded);parent.append(item.row)}}}refine.onchange=()=>{detail=refine.value;refinements.set(key+':'+mode,detail);order()};select.onchange=()=>{mode=select.value;detail=refinements.get(key+':'+mode)||'';refineOptions();try{if(shared)SamandisPreferences.set('sort:'+project?.id+':'+pid,mode).catch(e=>message('ترتیب نمایش ذخیره نشد: '+failure(e)));else localStorage.setItem(key,mode)}catch{}order()};order()}
const previous=render;render=function(...a){const r=previous(...a);attach();return r};const oldTasks=renderTasks;renderTasks=function(...a){const r=oldTasks(...a);attach();return r};attach();})();
